<template><div class="sf-field" :class="{'sf-field--error':!!error,'is-disabled':disabled}"><label :for="id">{{ label }}<span v-if="required" aria-hidden="true"> *</span></label><div class="sf-field__control"><component :is="multiline?'textarea':'input'" :id="id" :type="multiline?null:effectiveType" :value.prop="value" :placeholder="placeholder" :autocomplete="autocomplete" :inputmode="inputmode" :maxlength="maxlength" :required="required" :disabled="disabled" :readonly="readonly" :rows="multiline?rows:null" :aria-invalid="error?'true':null" :aria-describedby="error||help?id+'-description':null" @input="$emit('input',$event.target.value)" @change="$emit('change',$event.target.value)" @blur="$emit('blur',$event)"/><button v-if="type==='password'&&!multiline" type="button" class="sf-icon-button" :disabled="disabled" :aria-label="revealed?'Hide password':'Show password'" @click="revealed=!revealed"><sf-icon :name="revealed?'eye-off':'eye'"/></button></div><p v-if="error||help" :id="id+'-description'" :role="error?'alert':null">{{ error||help }}</p></div></template>
<script>
import SfIcon from './SfIcon'
let sequence=0
export default {name:'SfField',components:{SfIcon},props:{value:{type:[String,Number],default:''},label:{type:String,required:true},type:{type:String,default:'text'},placeholder:String,help:String,error:String,autocomplete:String,inputmode:String,maxlength:[Number,String],required:Boolean,disabled:Boolean,readonly:Boolean,multiline:Boolean,rows:{type:Number,default:3}},data(){return {id:'sf-field-'+(++sequence),revealed:false}},computed:{effectiveType(){return this.type==='password'&&this.revealed?'text':this.type}}}
</script>
